
const WORDS=[{"id": 0, "w": "四合院", "p": "sìhéyuàn", "t": "名词", "m": "tứ hợp viện", "coll": "一座四合院、四合院的照片", "s": "这本画册里有许多四合院的照片。"}, {"id": 1, "w": "民居", "p": "mínjū", "t": "名词", "m": "nhà ở của thường dân", "coll": "传统民居、当地民居", "s": "旅行时，她拍下了许多当地民居的照片。"}, {"id": 2, "w": "组合", "p": "zǔhé", "t": "动词／名词", "m": "kết hợp; tổ hợp", "coll": "组合在一起、重新组合", "s": "请把这几张图片组合在一起，做成一张海报。"}, {"id": 3, "w": "建筑", "p": "jiànzhù", "t": "名词", "m": "kiến trúc, công trình kiến trúc", "coll": "一座建筑、古老的建筑", "s": "河边有一座古老的建筑，吸引了许多游客。"}, {"id": 4, "w": "形式", "p": "xíngshì", "t": "名词", "m": "hình thức", "coll": "不同形式、活动形式", "s": "这次活动采用了学生们喜欢的形式。"}, {"id": 5, "w": "所谓", "p": "suǒwèi", "t": "形容词", "m": "cái gọi là", "coll": "所谓的成功、所谓的幸福", "s": "所谓幸福，不一定是拥有很多钱，也可以是家人在一起。"}, {"id": 6, "w": "方", "p": "fāng", "t": "形容词", "m": "vuông", "coll": "方桌、方形的盒子", "s": "这张桌子是方的，正好可以放在墙角。"}, {"id": 7, "w": "广泛", "p": "guǎngfàn", "t": "形容词", "m": "rộng rãi", "coll": "广泛使用、广泛讨论", "s": "这种方法已经在语言教学中得到广泛使用。"}, {"id": 8, "w": "样式", "p": "yàngshì", "t": "名词", "m": "hình thức, kiểu dáng", "coll": "衣服的样式、各种样式", "s": "这家店的衣服样式很多，她挑了很久。"}, {"id": 9, "w": "代表", "p": "dàibiǎo", "t": "动词／名词", "m": "đại biểu; đại diện", "coll": "代表班级、学生代表", "s": "她将代表我们班参加这次演讲比赛。"}, {"id": 10, "w": "通常", "p": "tōngcháng", "t": "副词", "m": "thường, bình thường", "coll": "通常情况下、通常做法", "s": "周末，他通常会去附近的公园散步。"}, {"id": 11, "w": "并列", "p": "bìngliè", "t": "动词", "m": "đặt song song, đứng cạnh nhau", "coll": "并列第一、并列放置", "s": "这次比赛有两名同学成绩相同，并列第一。"}, {"id": 12, "w": "组成", "p": "zǔchéng", "t": "动词", "m": "tạo thành, hợp thành", "coll": "由……组成、组成小组", "s": "这个学习小组由五名来自不同国家的学生组成。"}, {"id": 13, "w": "长辈", "p": "zhǎngbèi", "t": "名词", "m": "bề trên, bậc cha chú", "coll": "尊重长辈、家里的长辈", "s": "过节时，我们都会去看望家里的长辈。"}, {"id": 14, "w": "具备", "p": "jùbèi", "t": "动词", "m": "có đủ, có", "coll": "具备条件、具备能力", "s": "要做好这份工作，需要具备一定的沟通能力。"}, {"id": 15, "w": "日常", "p": "rìcháng", "t": "形容词", "m": "hằng ngày", "coll": "日常生活、日常用品", "s": "这家商店主要出售各种日常用品。"}, {"id": 16, "w": "起居", "p": "qǐjū", "t": "名词", "m": "sinh hoạt thường ngày", "coll": "起居室、日常起居", "s": "这间小房子虽然不大，却方便老人的日常起居。"}, {"id": 17, "w": "接待", "p": "jiēdài", "t": "动词", "m": "tiếp đãi", "coll": "接待客人、热情接待", "s": "客人到来时，主人热情地接待了大家。"}, {"id": 18, "w": "功能", "p": "gōngnéng", "t": "名词", "m": "chức năng", "coll": "主要功能、增加功能", "s": "这款软件增加了几个实用的功能。"}, {"id": 19, "w": "厢房", "p": "xiāngfáng", "t": "名词", "m": "chái nhà, hiên nhà", "coll": "东厢房、西厢房", "s": "画册中的院子有一间摆着旧家具的东厢房。"}, {"id": 20, "w": "走廊", "p": "zǒuláng", "t": "名词", "m": "hành lang, hàng hiên", "coll": "一条走廊、走廊尽头", "s": "沿着这条走廊往前走，就是老师的办公室。"}, {"id": 21, "w": "空间", "p": "kōngjiān", "t": "名词", "m": "không gian", "coll": "活动空间、节省空间", "s": "把桌子移到墙边，就能留出更多活动空间。"}, {"id": 22, "w": "种", "p": "zhòng", "t": "动词", "m": "trồng", "coll": "种花、种蔬菜", "s": "奶奶在院子里种了一些蔬菜。"}, {"id": 23, "w": "竹子", "p": "zhúzi", "t": "名词", "m": "cây trúc, cây tre", "coll": "一片竹子、种竹子", "s": "小路旁边有一片竹子，风吹过时，叶子轻轻地响。"}, {"id": 24, "w": "则", "p": "zé", "t": "连词", "m": "(chỉ sự tương phản) trong khi đó", "coll": "姐姐……弟弟则……、有的……有的则……", "s": "姐姐喜欢安静，弟弟则喜欢热闹。"}, {"id": 25, "w": "金鱼", "p": "jīnyú", "t": "名词", "m": "cá vàng", "coll": "一条金鱼、养金鱼", "s": "弟弟每天都认真地照顾鱼缸里的金鱼。"}, {"id": 26, "w": "创造", "p": "chuàngzào", "t": "动词", "m": "sáng tạo, tạo ra", "coll": "创造机会、创造价值", "s": "学校为学生们创造了很多交流的机会。"}, {"id": 27, "w": "情趣", "p": "qíngqù", "t": "名词", "m": "sự thú vị, điều thích thú", "coll": "生活情趣、富有情趣", "s": "在阳台上种些花草，能增添生活情趣。"}, {"id": 28, "w": "因而", "p": "yīn'ér", "t": "连词", "m": "do đó, vì vậy", "coll": "因而受到欢迎、因而改变计划", "s": "这家店价格合理、服务周到，因而很受欢迎。"}, {"id": 29, "w": "为", "p": "wéi", "t": "介词", "m": "(thường được dùng với \"所\") bị, được", "coll": "为大家所熟悉、为人所知", "s": "这个故事早已为当地居民所熟悉。"}, {"id": 30, "w": "关闭", "p": "guānbì", "t": "动词", "m": "đóng kín", "coll": "关闭窗户、关闭电源", "s": "离开教室前，请关闭电脑和电灯。"}, {"id": 31, "w": "封闭", "p": "fēngbì", "t": "动词", "m": "khép kín", "coll": "封闭自己、封闭的空间", "s": "他不愿总把自己封闭在狭小的生活圈里。"}, {"id": 32, "w": "打交道", "p": "dǎ jiāodao", "t": "动词", "m": "giao thiệp, tiếp xúc", "coll": "与人打交道、经常打交道", "s": "这份工作需要经常和不同的人打交道。"}, {"id": 33, "w": "日子", "p": "rìzi", "t": "名词", "m": "cuộc sống", "coll": "日子过得好、平静的日子", "s": "他们靠自己的努力，让日子越过越好。"}, {"id": 34, "w": "充分", "p": "chōngfèn", "t": "形容词", "m": "đầy đủ, trọn vẹn", "coll": "充分准备、充分利用", "s": "出发前，我们已经做好了充分的准备。"}, {"id": 35, "w": "令", "p": "lìng", "t": "动词", "m": "khiến, làm cho", "coll": "令人感动、令人高兴", "s": "这个好消息令大家十分高兴。"}, {"id": 36, "w": "亲切", "p": "qīnqiè", "t": "形容词", "m": "thân mật, thân thiết", "coll": "亲切的笑容、感到亲切", "s": "老师亲切地和新同学打了招呼。"}, {"id": 37, "w": "劳动", "p": "láodòng", "t": "动词／名词", "m": "lao động, công việc; làm việc, lao động (bằng chân tay)", "coll": "参加劳动、体力劳动", "s": "周末，学生们一起参加了校园劳动。"}, {"id": 38, "w": "人民", "p": "rénmín", "t": "名词", "m": "nhân dân", "coll": "为人民服务、人民的生活", "s": "这部电影生动地展现了人民的日常生活。"}, {"id": 39, "w": "矛盾", "p": "máodùn", "t": "名词／形容词", "m": "sự mâu thuẫn; mâu thuẫn", "coll": "发生矛盾、解决矛盾", "s": "有了矛盾，双方应该坐下来好好沟通。"}, {"id": 40, "w": "浓", "p": "nóng", "t": "形容词", "m": "sâu sắc, đậm", "coll": "茶味很浓、浓厚的感情", "s": "这杯茶的味道有点儿浓，我想加一点儿水。"}];
